from pathlib import Path
# Define transformed cell-coordinate mapping and program function.
def _coords(H,W,kind,r,c):
    if kind=='id': return r,c
    if kind=='h': return r,W-1-c
    if kind=='v': return H-1-r,c
    if kind=='180': return H-1-r,W-1-c
    if kind=='t': return c,r
    if kind=='a': return W-1-c,H-1-r
    if kind=='cw': return c,H-1-r
    if kind=='ccw': return W-1-c,r

def _corners(H,W):
    return {'TL':(0,0),'TR':(0,W-1),'BL':(H-1,0),'BR':(H-1,W-1)}

def transform(grid):
    H0,W0=len(grid),len(grid[0])
    ones=[(r,c) for r in range(H0) for c in range(W0) if grid[r][c]==1]
    r0=min(r for r,c in ones); r1=max(r for r,c in ones)
    c0=min(c for r,c in ones); c1=max(c for r,c in ones)
    src=[row[c0:c1+1] for row in grid[r0:r1+1]]
    H,W=len(src),len(src[0])
    # Exterior clue colors are the non-background cells outside the 1-rectangle.
    clues={}
    for r in range(H0):
        for c in range(W0):
            v=grid[r][c]
            if v not in (0,1) and not (r0<=r<=r1 and c0<=c<=c1):
                clues.setdefault(v,[]).append((r,c))
    cluepts={k:pts[0] for k,pts in clues.items() if len(pts)==1}
    # Label the three positions in the exterior L by its horizontal and vertical arms.
    target={}
    vals=list(cluepts)
    if len(vals)==3:
        shared=None; hpair=None; vpair=None
        for i in range(3):
            for j in range(i+1,3):
                a,b=vals[i],vals[j]
                if cluepts[a][0]==cluepts[b][0]: hpair=(a,b)
                if cluepts[a][1]==cluepts[b][1]: vpair=(a,b)
        if hpair and vpair:
            sh=set(hpair)&set(vpair)
            if len(sh)==1:
                shared=next(iter(sh))
                hp=next(x for x in hpair if x!=shared)
                vp=next(x for x in vpair if x!=shared)
                sy,sx=cluepts[shared]; hy,hx=cluepts[hp]; vy,vx=cluepts[vp]
                row_side='T' if sy<vy else 'B'
                col_side='L' if sx<hx else 'R'
                target[shared]=row_side+col_side
                target[hp]=row_side+('R' if col_side=='L' else 'L')
                target[vp]=('B' if row_side=='T' else 'T')+col_side
    marker_positions={}
    for r in range(H):
        for c in range(W):
            v=src[r][c]
            if v not in (0,1) and v in target:
                marker_positions.setdefault(v,[]).append((r,c))
    kinds=['id','h','v','180','t','a','cw','ccw']
    def outdims(kind): return (H,W) if kind in ('id','h','v','180') else (W,H)
    # Prefer transformations that place each in-rectangle marker closest to its external clue corner.
    scores=[]
    for kind in kinds:
        oh,ow=outdims(kind); corners=_corners(oh,ow)
        score=0
        for color,positions in marker_positions.items():
            if color not in target: continue
            cr,cc=corners[target[color]]
            for r,c in positions:
                rr,cc2=_coords(H,W,kind,r,c)
                score+=abs(rr-cr)+abs(cc2-cc)
        scores.append((score,kind))
    kind=min(scores)[1]
    oh,ow=outdims(kind)
    out=[[1]*ow for _ in range(oh)]
    motif_colors={src[r][c] for r in range(H) for c in range(W) if src[r][c] not in (0,1) and src[r][c] not in target}
    motif_color=next(iter(motif_colors)) if len(motif_colors)==1 else None
    motif=[]
    for r in range(H):
        for c in range(W):
            v=src[r][c]
            rr,cc=_coords(H,W,kind,r,c)
            if v==1 or v in target:
                out[rr][cc]=v
            elif v==motif_color:
                motif.append((rr,cc))
    if motif:
        mr=min(r for r,c in motif); mc=min(c for r,c in motif)
        mh=max(r for r,c in motif)-mr+1; mw=max(c for r,c in motif)-mc+1
        tr=(oh-mh)//2; tc=(ow-mw)//2
        for r,c in motif:
            out[tr+(r-mr)][tc+(c-mc)]=motif_color
    return out
